/* ==========================================================================
   Just Say No to `curl | bash`
   A single, dependency-free stylesheet. Retro public-service-announcement
   vibes (warm paper, red ribbon, warning tape) meets terminal green.
   ========================================================================== */

:root {
  --ink: #1b1a17;
  --ink-soft: #4a463f;
  --paper: #f6f1e7;
  --paper-2: #efe7d6;
  --red: #d4242c;
  --red-dark: #9c1118;
  --amber: #f4b400;
  --term-bg: #15140f;
  --term-green: #67e480;
  --term-amber: #f4c95d;
  --term-red: #ff6b6b;
  --term-dim: #8a8775;
  --good: #1e8a4c;
  --line: #d8cdb6;
  --shadow: 0 2px 0 rgba(0, 0, 0, 0.12), 0 8px 24px rgba(27, 26, 23, 0.12);
  --radius: 10px;
  --maxw: 980px;
  --mono: ui-monospace, "SF Mono", "Cascadia Code", "JetBrains Mono", Menlo, Consolas, monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--sans);
  color: var(--ink);
  background-color: var(--paper);
  background-image:
    radial-gradient(circle at 1px 1px, rgba(27, 26, 23, 0.05) 1px, transparent 0);
  background-size: 22px 22px;
  line-height: 1.65;
  font-size: 18px;
  -webkit-font-smoothing: antialiased;
}

/* ----- Skip link (a11y) ----- */
.skip {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--ink);
  color: var(--paper);
  padding: 10px 16px;
  z-index: 100;
}
.skip:focus { left: 8px; top: 8px; }

/* ----- Warning tape ----- */
.tape {
  height: 26px;
  background: repeating-linear-gradient(
    -45deg,
    var(--amber) 0 22px,
    var(--ink) 22px 44px
  );
  border-top: 2px solid var(--ink);
  border-bottom: 2px solid var(--ink);
}

/* ----- Layout ----- */
.wrap { max-width: var(--maxw); margin: 0 auto; padding: 0 22px; }
section { padding: 56px 0; border-bottom: 2px dashed var(--line); }
section:last-of-type { border-bottom: none; }

a { color: var(--red-dark); }
a:hover { color: var(--red); }

h1, h2, h3 { line-height: 1.12; letter-spacing: -0.01em; }
h2 {
  font-size: clamp(1.6rem, 4vw, 2.4rem);
  margin: 0 0 0.4em;
  text-transform: uppercase;
}
h2 .num {
  display: inline-block;
  background: var(--ink);
  color: var(--amber);
  font-family: var(--mono);
  font-size: 0.7em;
  padding: 0 0.4em;
  margin-right: 0.4em;
  border-radius: 4px;
  vertical-align: 0.12em;
}
h3 { font-size: 1.25rem; margin: 1.4em 0 0.4em; }
.lead { font-size: 1.15rem; color: var(--ink-soft); }

/* ----- Header / Hero ----- */
header.hero {
  background:
    linear-gradient(180deg, rgba(212, 36, 44, 0.06), rgba(212, 36, 44, 0) 60%);
  text-align: center;
  padding: 46px 0 40px;
  position: relative;
}
.hero h1 {
  font-size: clamp(2.3rem, 8vw, 4.6rem);
  margin: 18px 0 6px;
  text-transform: uppercase;
  font-weight: 900;
}
.hero h1 code {
  display: inline-block;
  background: var(--term-bg);
  color: var(--term-green);
  padding: 0 0.18em;
  border-radius: 8px;
  font-size: 0.78em;
  transform: rotate(-1.2deg);
  box-shadow: var(--shadow);
}
.hero .subtitle {
  font-size: clamp(1.05rem, 2.6vw, 1.35rem);
  color: var(--ink-soft);
  max-width: 40ch;
  margin: 0.6em auto 0;
}

/* ----- "Just Say No" seal ----- */
.seal {
  width: 132px;
  height: 132px;
  margin: 0 auto;
  border-radius: 50%;
  background: var(--red);
  color: #fff;
  display: grid;
  place-content: center;
  text-align: center;
  border: 6px solid #fff;
  box-shadow: 0 0 0 4px var(--red-dark), var(--shadow);
  transform: rotate(-6deg);
  font-weight: 900;
  text-transform: uppercase;
  line-height: 1;
}
.seal .big { font-size: 1.5rem; letter-spacing: 0.02em; }
.seal .small { font-size: 0.62rem; letter-spacing: 0.18em; margin-top: 4px; }

/* ----- Buttons ----- */
.cta-row {
  display: flex;
  gap: 14px;
  justify-content: center;
  flex-wrap: wrap;
  margin-top: 28px;
}
.btn {
  display: inline-block;
  font-weight: 800;
  text-decoration: none;
  padding: 14px 22px;
  border-radius: var(--radius);
  border: 2px solid var(--ink);
  background: var(--paper-2);
  color: var(--ink);
  box-shadow: var(--shadow);
  transition: transform 0.08s ease;
  text-transform: uppercase;
  font-size: 0.95rem;
  letter-spacing: 0.02em;
}
.btn:hover { transform: translateY(-2px); color: var(--ink); }
.btn:active { transform: translateY(0); }
.btn.primary { background: var(--red); color: #fff; border-color: var(--red-dark); }
.btn.primary:hover { color: #fff; }

/* ----- Terminal block ----- */
.term {
  background: var(--term-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
  margin: 22px 0;
  font-family: var(--mono);
  font-size: 0.92rem;
  text-align: left;
}
.term .bar {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 9px 12px;
  background: #211f18;
  border-bottom: 1px solid #000;
}
.term .bar i {
  width: 12px; height: 12px; border-radius: 50%; display: inline-block;
}
.term .bar .r { background: #ff5f56; }
.term .bar .y { background: #ffbd2e; }
.term .bar .g { background: #27c93f; }
.term .bar span {
  margin-left: 8px; color: var(--term-dim); font-size: 0.8rem;
}
.term pre {
  margin: 0;
  padding: 16px 18px;
  color: var(--term-green);
  overflow-x: auto;
  line-height: 1.55;
}
.term .prompt { color: var(--term-dim); }
.term .cmd { color: #fff; }
.term .bad { color: var(--term-red); }
.term .ok { color: var(--term-green); }
.term .warn { color: var(--term-amber); }
.term .cmt { color: var(--term-dim); }

/* ----- Cards ----- */
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 18px;
  margin-top: 26px;
}
.card {
  background: #fff;
  border: 2px solid var(--ink);
  border-radius: var(--radius);
  padding: 22px;
  box-shadow: var(--shadow);
}
.card .icon { font-size: 1.8rem; }
.card h3 { margin-top: 0.5em; }
.card p { margin: 0.5em 0 0; color: var(--ink-soft); font-size: 0.98rem; }

/* ----- Two audience paths ----- */
.paths {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-top: 24px;
}
.path {
  border: 3px solid var(--ink);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
}
.path.users { background: #eef5ef; }
.path.distros { background: #f0eef7; }
.path h3 { margin-top: 0; font-size: 1.4rem; }
.path .who { font-family: var(--mono); font-size: 0.8rem; color: var(--ink-soft); text-transform: uppercase; letter-spacing: 0.12em; }

/* ----- Lists ----- */
ul.checks, ul.crosses { list-style: none; padding-left: 0; }
ul.checks li, ul.crosses li { padding-left: 1.9em; position: relative; margin: 0.5em 0; }
ul.checks li::before { content: "✓"; position: absolute; left: 0; color: var(--good); font-weight: 900; }
ul.crosses li::before { content: "✕"; position: absolute; left: 0; color: var(--red); font-weight: 900; }

/* ----- Callout ----- */
.callout {
  border-left: 6px solid var(--amber);
  background: var(--paper-2);
  padding: 16px 20px;
  border-radius: 0 var(--radius) var(--radius) 0;
  margin: 22px 0;
}
.callout.danger { border-left-color: var(--red); background: #fbe9ea; }
.callout strong { text-transform: uppercase; letter-spacing: 0.03em; font-size: 0.85rem; }

/* ----- Comparison table ----- */
.cmp { width: 100%; border-collapse: collapse; margin-top: 22px; font-size: 0.95rem; }
.cmp th, .cmp td { border: 1px solid var(--line); padding: 11px 13px; text-align: left; vertical-align: top; }
.cmp thead th { background: var(--ink); color: var(--paper); text-transform: uppercase; font-size: 0.8rem; letter-spacing: 0.04em; }
.cmp tbody tr:nth-child(even) { background: var(--paper-2); }
.cmp .yes { color: var(--good); font-weight: 700; }
.cmp .no { color: var(--red); font-weight: 700; }

/* ----- FAQ ----- */
.faq details {
  border: 2px solid var(--ink);
  border-radius: var(--radius);
  margin: 12px 0;
  background: #fff;
  box-shadow: var(--shadow);
}
.faq summary {
  cursor: pointer;
  padding: 16px 20px;
  font-weight: 800;
  list-style: none;
}
.faq summary::-webkit-details-marker { display: none; }
.faq summary::before { content: "▸ "; color: var(--red); }
.faq details[open] summary::before { content: "▾ "; }
.faq details > *:not(summary) { padding: 0 20px 18px; margin: 0; color: var(--ink-soft); }

/* ----- The Pledge ----- */
.pledge {
  background: var(--ink);
  color: var(--paper);
  text-align: center;
}
.pledge h2 { color: var(--amber); }
.pledge .scroll {
  max-width: 640px;
  margin: 0 auto;
  background: var(--paper);
  color: var(--ink);
  border-radius: var(--radius);
  padding: 30px 34px;
  box-shadow: var(--shadow);
  text-align: left;
  font-size: 1.05rem;
}
.pledge .scroll ol { margin: 0; padding-left: 1.3em; }
.pledge .scroll li { margin: 0.6em 0; }
.pledge .sign { margin-top: 22px; font-family: var(--mono); color: var(--ink-soft); border-top: 1px dashed var(--line); padding-top: 14px; }

/* ----- Footer ----- */
footer {
  background: var(--ink);
  color: var(--term-dim);
  padding: 36px 0;
  font-size: 0.9rem;
}
footer a { color: var(--term-amber); }
footer a:hover { color: var(--amber); }
footer .cols { display: flex; flex-wrap: wrap; gap: 36px; justify-content: space-between; }
footer h4 { color: var(--paper); margin: 0 0 0.6em; text-transform: uppercase; font-size: 0.85rem; letter-spacing: 0.06em; }
footer ul { list-style: none; padding: 0; margin: 0; }
footer li { margin: 0.3em 0; }
footer .fine { margin-top: 26px; border-top: 1px solid #2c2a22; padding-top: 18px; color: #6f6c5e; }

/* ----- Inline code ----- */
code {
  font-family: var(--mono);
  background: var(--paper-2);
  border: 1px solid var(--line);
  border-radius: 5px;
  padding: 0.08em 0.36em;
  font-size: 0.9em;
}

/* ----- Copy button ----- */
.copy {
  font-family: var(--mono);
  font-size: 0.75rem;
  background: transparent;
  border: 1px solid var(--term-dim);
  color: var(--term-dim);
  border-radius: 5px;
  padding: 2px 8px;
  cursor: pointer;
  margin-left: auto;
}
.copy:hover { color: var(--paper); border-color: var(--paper); }

/* ----- Sub-page nav ----- */
.subnav {
  background: var(--ink);
  color: var(--paper);
  padding: 12px 0;
  font-family: var(--mono);
  font-size: 0.9rem;
}
.subnav .wrap { display: flex; gap: 18px; align-items: center; flex-wrap: wrap; }
.subnav a { color: var(--term-green); text-decoration: none; }
.subnav a:hover { color: #fff; }
.subnav .home { color: var(--amber); font-weight: 700; }

/* ----- Responsive ----- */
@media (max-width: 720px) {
  body { font-size: 17px; }
  .paths { grid-template-columns: 1fr; }
  section { padding: 40px 0; }
}

/* ----- Motion-reduced ----- */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .btn { transition: none; }
}

