from html.parser import HTMLParser
import sys
class V(HTMLParser):
    voids={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
    def __init__(s):
        super().__init__(); s.stack=[]; s.errs=[]
    def handle_starttag(s,t,a):
        if t not in s.voids: s.stack.append(t)
    def handle_endtag(s,t):
        if t in s.voids: return
        if s.stack and s.stack[-1]==t: s.stack.pop()
        elif t in s.stack:
            while s.stack and s.stack.pop()!=t: pass
        else: s.errs.append('stray </%s>'%t)
for f in ['index.html','how-it-works.html']:
    v=V(); v.feed(open(f).read())
    print(f, '-> unclosed:', v.stack, '| errs:', v.errs[:5])
"

